'use strict';
// Calibration uses acquired, integrated peaks; prepared truth never enters back-calculation.
const gcal={mode:'internal',analyte:'ethanol',is:'propanol',vials:[],points:[],results:[],method:null,loaded:null,message:'Prepare vials, load one into the injector, then operate the GC-FID above. Completed runs are added automatically.',form:{stock:2,aliquot:2,final:10,isStock:2,isVolume:2,role:'standard'},next:1};
try{const v=JSON.parse(localStorage.getItem('simlab-gc-calibration')||'null');if(v&&['external','internal'].includes(v.mode)&&GC_COMPOUNDS.some(c=>c.id===v.analyte)&&GC_COMPOUNDS.some(c=>c.id===v.is)&&v.analyte!==v.is){Object.assign(gcal,v);gcal.loaded=null;}}catch{}
function gcCalSave(){try{localStorage.setItem('simlab-gc-calibration',JSON.stringify(gcal))}catch{}}
function gcCalName(id){return GC_COMPOUNDS.find(c=>c.id===id)?.name||id}
function gcCalKey(m){const keys=['gas','injectionTime','column','length','id','film','injector','detector','flow','ovenMode','initial','hold','ramp','final','finalHold','runtime','splitMode','split'];if(gcal.mode==='external')keys.push('volume');return JSON.stringify(keys.map(k=>[k,m[k]]))}
function gcCalPrepare(f){const solvent=f.solvent||'water';if(!GC_SOLVENTS.some(s=>s.id===solvent))throw Error('Select a supported diluent.');if(f.role!=='blank'&&(solvent===gcal.analyte||(gcal.mode==='internal'&&solvent===gcal.is)))throw Error('The diluent cannot be the analyte or internal standard.');if(f.role==='blank'){if(!Number.isFinite(f.final)||f.final<=0)throw Error('Enter a positive final volume.');return {id:gcal.next++,role:'blank',label:String(f.label||'').slice(0,60),solvent,concentration:0,isC:0,preparation:{...f},mix:{}};}for(const k of ['stock','aliquot','final','isStock','isVolume'])if(!Number.isFinite(f[k])||f[k]<0)throw Error('Enter finite, non-negative preparation values.');if(f.stock<=0||f.aliquot<=0||f.final<=0)throw Error('Stock concentration, aliquot and final volume must be positive.');const internal=gcal.mode==='internal';if(internal&&(f.isStock<=0||f.isVolume<=0))throw Error('Add a positive known internal-standard spike.');if(f.aliquot+(internal?f.isVolume:0)>f.final+1e-9)throw Error('The combined aliquot and spike volumes cannot exceed the final solution volume.');const concentration=f.stock*f.aliquot/f.final,isC=internal?f.isStock*f.isVolume/f.final:0;if(concentration>20||isC>20)throw Error('Final component concentrations must not exceed 20 mg/mL.');return {id:gcal.next++,label:String(f.label||'').slice(0,60),solvent,role:f.role==='unknown'?'unknown':'standard',concentration,isC,preparation:{...f},mix:{[gcal.analyte]:concentration,...(internal?{[gcal.is]:isC}:{})}}}
function gcCalFit(points=gcal.points){if(points.length<3||new Set(points.map(p=>p.x)).size<3)return null;const n=points.length,mx=points.reduce((s,p)=>s+p.x,0)/n,my=points.reduce((s,p)=>s+p.y,0)/n,sxx=points.reduce((s,p)=>s+(p.x-mx)**2,0),syy=points.reduce((s,p)=>s+(p.y-my)**2,0);if(!(sxx>0&&syy>0))return null;const slope=points.reduce((s,p)=>s+(p.x-mx)*(p.y-my),0)/sxx,intercept=my-slope*mx;if(!(slope>0&&Number.isFinite(slope)))return null;const residual=points.reduce((s,p)=>s+(p.y-slope*p.x-intercept)**2,0);return {slope,intercept,r2:1-residual/syy,min:Math.min(...points.map(p=>p.x)),max:Math.max(...points.map(p=>p.x)),n}}
function gcCalBackcalculate(fit,y,isC=1,dilution=1){if(!fit)throw Error('Acquire at least three distinct calibration levels before analysing an unknown.');const x=(y-fit.intercept)/fit.slope;if(!Number.isFinite(x)||x<0)throw Error('The response gives a negative or invalid concentration. Check the calibration and peak assignment.');return {vial:x*(gcal.mode==='internal'?isC:1),original:x*(gcal.mode==='internal'?isC:1)*dilution,extrapolated:x<fit.min||x>fit.max}}
function gcCalPeak(run,id){const p=run.peaks.find(p=>p.ids.includes(id));if(!p||p.partial||p.overlap||p.ids.length!==1||!(p.area>0))throw Error(gcCalName(id)+': a complete, resolved peak is required. Adjust the method and repeat the run.');return p}
function gcCalRunTag(){const vial=gcal.vials.find(v=>v.id===gcal.loaded);if(!vial)return null;const a=Object.keys(vial.mix),b=Object.keys(gc.mix).filter(k=>gc.mix[k]>0);if(a.length!==b.length||a.some(k=>Math.abs(gc.mix[k]-vial.mix[k])>1e-9))return null;return JSON.parse(JSON.stringify({...vial,mode:gcal.mode,analyte:gcal.analyte,is:gcal.is}))}
function gcCalibrationFinished(run){if(!run.calibration||!run.completed||run.calibrationRecorded)return;if(gcIsMS(run.method)){run.calibrationError=null;gcal.message='MS run acquired directly. Review spectra in MS data analysis; FID calibration data are unchanged.';gcCalSave();return}run.calibrationRecorded=true;const v=run.calibration;run.calibrationError=null;if(v.role==='mixture'){gcal.message='Separation mixture acquired. Review component retention times, areas and resolution in the chromatogram; no calibration point is added.';gcCalSave();return}if(v.role==='blank'){gcal.message='Solvent blank acquired; no analyte calibration point is added.';gcCalSave();return}try{if(v.mode!==gcal.mode||v.analyte!==gcal.analyte||v.is!==gcal.is||!gcal.vials.some(x=>x.id===v.id))throw Error('This run belongs to a previous calibration.');const key=gcCalKey(run.method);if(gcal.method&&key!==gcal.method)throw Error('Method differs from the calibration. Restore the calibration method or start a new calibration. External calibration requires the same injection volume; internal calibration permits volume changes.');const a=gcCalPeak(run,gcal.analyte),i=gcal.mode==='internal'?gcCalPeak(run,gcal.is):null,y=i?a.area/i.area:a.area,point={id:v.id,label:gcVialLabel(v),concentration:v.concentration,isC:v.isC,area:a.area,isArea:i?.area||0,tr:a.tr,isTr:i?.tr||0,x:i?v.concentration/v.isC:v.concentration,y,volume:run.method.volume};if(v.role==='standard'){gcal.points=gcal.points.filter(p=>p.id!==v.id);gcal.points.push(point);gcal.method=key;gcal.message='Standard '+v.id+' acquired from integrated peak areas. '+gcal.points.length+' measured vial(s).';}else{const fit=gcCalFit(),dilution=v.preparation.final/v.preparation.aliquot,result=gcCalBackcalculate(fit,y,v.isC,dilution);gcal.results.push({...point,...result,fit:{...fit},dilution});gcal.results=gcal.results.slice(-20);gcal.message='Unknown '+v.id+' calculated from the measured response and calibration curve.';}gcCalSave()}catch(e){run.calibrationError=e.message;gcal.message='Run excluded: '+e.message;gcCalSave()}}
function gcCalLoad(id){const v=gcal.vials.find(v=>v.id===id);if(!v||gcLocked())return;if(gc.run?.completed||gc.run?.stopped)gc.preparingNext=true;gcal.loaded=id;gc.mix={...v.mix};gc.sample=v.role==='blank'?'blank':'custom';gcal.message=gcVialLabel(v)+' loaded. Equilibrate if needed, ignite the FID and inject above.';gcCalSave();gcCalRefresh()}
function gcCalCurve(){const f=gcCalFit(),ps=gcal.points;if(!ps.length)return '<div class="gcal-empty">Your curve will appear as standards finish running.</div>';const maxX=Math.max(...ps.map(p=>p.x))*1.15||1,maxY=Math.max(...ps.map(p=>p.y),f?f.slope*maxX+f.intercept:0)*1.1||1,X=x=>65+x/maxX*475,Y=y=>225-y/maxY*185;let grid='';for(let j=0;j<=4;j++){let x=maxX*j/4,y=maxY*j/4;grid+=`<path d="M65 ${Y(y)}H540 M${X(x)} 40V225" stroke="#e2eae5"/><text x="55" y="${Y(y)+4}" text-anchor="end">${gcFmt(y,2)}</text><text x="${X(x)}" y="244" text-anchor="middle">${gcFmt(x,2)}</text>`}return `<svg viewBox="0 0 580 290" role="img" aria-label="Measured calibration points and linear regression"><rect width="580" height="290" fill="#fbfdfb"/>${grid}<path d="M65 40V225H540" fill="none" stroke="#71807c"/>${f?`<path d="M${X(Math.max(0,-f.intercept/f.slope))} ${Y(Math.max(0,f.intercept))}L${X(maxX)} ${Y(f.slope*maxX+f.intercept)}" stroke="#087e67" stroke-width="2"/>`:''}${ps.map(p=>`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="5" fill="#bd7541"><title>${gcPrepEsc(p.label)}: x ${p.x}, y ${p.y}</title></circle>`).join('')}<text x="302" y="274" text-anchor="middle">${gcal.mode==='internal'?'Concentration ratio · C analyte / C IS':'Analyte concentration / mg mL⁻¹'}</text><text x="20" y="133" transform="rotate(-90 20 133)" text-anchor="middle">${gcal.mode==='internal'?'Peak area ratio · A analyte / A IS':'Peak area / pA·s'}</text></svg>`}
function gcCalInput(label,key){return `<label class="gc-field">${label}<input data-gcal-number="${key}" type="number" min="0" step="any" value="${gcal.form[key]}" ${gcLocked()?'disabled':''}></label>`}
document.addEventListener('input',e=>{if(typeof page==='undefined'||!['instrumentation','bench'].includes(page)||gcLocked()||(typeof gseq!=='undefined'&&gseq.active))return;const key=e.target.dataset.gcalNumber;if(key){gcal.form[key]=Number(e.target.value);gcCalSave()}});
function gcCalibrationPanel(){const f=gcCalFit(),internal=gcal.mode==='internal';return `<section class="panel gc-panel gcal-panel" id="gcCalibration"><div class="gc-titlebar"><div><span class="eyebrow">QUANTITATION</span><h2>Calibration &amp; sample results</h2></div><button class="btn secondary small" data-gprep-action="bench">Prepare standards at Open bench ↗</button></div><p>${internal?'Internal':'External'} calibration · ${gcCalName(gcal.analyte)}${internal?' / '+gcCalName(gcal.is):''}. Preparation and the vial rack are in Open bench.</p><div class="gcal-curve">${gcCalCurve()}</div>${f?`<div class="gc-notice"><b>y = ${gcFmt(f.slope,6)} x ${f.intercept<0?'−':'+'} ${gcFmt(Math.abs(f.intercept),6)}</b><br>R² = ${gcFmt(f.r2,6)} · ${f.n} points · linear fit with intercept.<br>${internal?'C vial = C IS × (area ratio − intercept) / slope.':'C vial = (area − intercept) / slope.'}</div>`:'<p>Run at least three distinct standards to fit a calibration curve.</p>'}<div class="gc-notice" role="status">${gcPrepEsc(gcal.message)}</div><h3>Measured standards</h3><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Vial</th><th>C / mg mL⁻¹</th><th>Analyte area / pA·s</th>${internal?'<th>IS area / pA·s</th><th>C / C IS</th><th>Area / Area IS</th>':''}<th>Injection / µL</th><th>Residual y − fit</th></tr></thead><tbody>${gcal.points.map(p=>`<tr><td>${gcPrepEsc(p.label)}</td><td>${gcFmt(p.concentration,4)}</td><td>${gcFmt(p.area,4)}</td>${internal?`<td>${gcFmt(p.isArea,4)}</td><td>${gcFmt(p.x,4)}</td><td>${gcFmt(p.y,5)}</td>`:''}<td>${p.volume}</td><td>${f?gcFmt(p.y-f.slope*p.x-f.intercept,6):'—'}</td></tr>`).join('')||'<tr><td colspan="8">Run a prepared standard to collect a point.</td></tr>'}</tbody></table></div><h3>Unknown results</h3><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Sample</th><th>C in vial / mg mL⁻¹</th><th>Dilution factor</th><th>C original / mg mL⁻¹</th><th>Assessment</th></tr></thead><tbody>${gcal.results.map(p=>`<tr><td>${gcPrepEsc(p.label)}</td><td>${gcFmt(p.vial,5)}</td><td>${gcFmt(p.dilution,3)}</td><td>${gcFmt(p.original,5)}</td><td>${p.extrapolated?'Outside calibration range · dilute or extend standards':'Within calibration range'} · fit R² ${gcFmt(p.fit.r2,5)}</td></tr>`).join('')||'<tr><td colspan="5">Fit a curve, then run a prepared unknown.</td></tr>'}</tbody></table></div><div class="gc-actions"><button class="btn secondary small" data-gcal-action="export" ${!gcal.points.length?'disabled':''}>Export calibration & results CSV</button></div><details class="gc-detail"><summary>Method matching, assumptions and references</summary><p>Only complete runs with resolved, non-truncated peaks contribute. Peak identities come from the simulated sample assignment. External calibration requires the same method and injection volume. Internal calibration uses analyte/IS ratios and permits a different injection volume while other method settings remain fixed. Changes to column, temperatures, flow or split require a new calibration. Results outside the calibration range are flagged. A high R² alone does not validate a method.</p><p>Internal-standard equations follow <a href="https://openlab.help.agilent.com/en/mergedProjects/DataAnalysis/45035999678838923.htm" target="_blank" rel="noopener">Agilent OpenLab’s internal-standard calculation</a>. Alcohol identities, molecular masses and boiling points are referenced to NIST in the instrument notebook. Retention and FID response factors remain illustrative teaching models, not experimental calibration data. Sample and IS preparation are assumed exact; matrix effects and uncertainty are not modelled. Vials and calibration data are stored on this browser when storage is available.</p></details></section>`}
document.addEventListener('change',e=>{if(typeof page==='undefined'||!['instrumentation','bench'].includes(page)||gcLocked()||(typeof gseq!=='undefined'&&gseq.active))return;const t=e.target;if(t.dataset.gcalNumber){gcal.form[t.dataset.gcalNumber]=Number(t.value);gcCalSave()}if(t.dataset.gcalConfig){const k=t.dataset.gcalConfig;if(k==='role')gcal.form.role=t.value;else if(!gcal.vials.length){gcal[k]=t.value;if(gcal.analyte===gcal.is){gcal.is=GC_COMPOUNDS.find(c=>c.id!==gcal.analyte&&['ethanol','methanol','propanol'].includes(c.id)).id;gcal.message='The internal standard was changed to keep it different from the analyte.'}}gcCalSave();gcCalRefresh()}});
document.addEventListener('click',e=>{if(typeof page==='undefined'||!['instrumentation','bench'].includes(page)||gcLocked()||(typeof gseq!=='undefined'&&gseq.active))return;const load=e.target.closest('[data-gcal-load]');if(load){gcCalLoad(Number(load.dataset.gcalLoad));return}const action=e.target.closest('[data-gcal-action]')?.dataset.gcalAction;if(!action)return;try{if(action==='new'){gcal.vials=[];gcal.points=[];gcal.results=[];gcal.method=null;gcal.loaded=null;gcal.next=1;gseq.queue=[];gseq.current=null;gcSequenceSave();gcal.message='New calibration. Select compounds and method, then prepare fresh vials.';}else if(action==='method'){gc.method={...gcDefaults(),detectorType:gc.method.detectorType||'fid',column:'pdms',ovenMode:'isothermal',initial:60,runtime:8};gc.ready=false;gc.flame=false;gc.finishedTemp=null;gcal.message='Alcohol method loaded: PDMS, 60 °C, 8 min, 1 µL, split 50:1. Equilibrate and ignite the FID before injection.';}else if(action==='prepare'){if(gcal.vials.length>=30)throw Error('Start a new calibration after 30 prepared vials.');gcal.vials.push(gcCalPrepare(gcal.form));gcal.message='Vial prepared. Export it to GC-FID, then choose Load sample or Set sequence.';}else if(action==='example'){if(gcal.vials.length>25)throw Error('Too many vials; start a new calibration.');for(const aliquot of [.5,1,2,3,4])gcal.vials.push(gcCalPrepare({stock:2,aliquot,final:10,isStock:2,isVolume:2,role:'standard',solvent:gcal.form.solvent||'water'}));gcal.message='Five standards prepared: 0.1, 0.2, 0.4, 0.6 and 0.8 mg/mL'+(gcal.mode==='internal'?', each with 0.4 mg/mL IS.':'.')+' Export the vials to GC-FID and run the sequence.';}else if(action==='export'){const f=gcCalFit();gcDownload('SIMLAB-GCFID-calibration.csv',[['SIMULATED calibration',gcal.mode,'analyte',gcCalName(gcal.analyte),'IS',gcal.mode==='internal'?gcCalName(gcal.is):'none'],['fit slope',f?.slope,'intercept',f?.intercept,'R_squared',f?.r2],['method fingerprint',gcal.method],['role','vial','C_standard_mg_mL','C_IS_mg_mL','area_analyte_pA_s','area_IS_pA_s','x','y','C_vial_calculated_mg_mL','dilution','C_original_calculated_mg_mL','extrapolated','fit_slope','fit_intercept','fit_R_squared'],...gcal.points.map(p=>['standard',p.id,p.concentration,p.isC,p.area,p.isArea,p.x,p.y,'','','','',f?.slope,f?.intercept,f?.r2]),...gcal.results.map(p=>['unknown',p.id,'',p.isC,p.area,p.isArea,'',p.y,p.vial,p.dilution,p.original,p.extrapolated,p.fit.slope,p.fit.intercept,p.fit.r2])]);}}catch(err){gcal.message=err.message}gcCalSave();gcCalRefresh()});
